      "actor": {
        "id": "uuid",
        "name": "Tuğçe Konu",
        "avatarColor": "#6366f1",
        "initials": "TK"
      },
      "metadata": {
        "fromValue": "new_task",
        "fromLabel": "Yapılacak",
        "toValue": "in_progress",
        "toLabel": "Devam Ediyor"
