        "avatarColor": "#6366f1",
        "initials": "TK"
      },
      "metadata": {
        "fileName": "Katılımcı_Listesi.pdf",
        "fileSize": "2.3MB"
      },
      "createdAt": "2026-03-27T11:00:00.000Z"
    },
    {
      "id": "uuid",
      "action": "alternative_added",
      "actor": {
        "id": "uuid",
        "name": "Tuğçe Konu",
        "avatarColor": "#6366f1",
        "initials": "TK"
      },
      "metadata": {
        "vendor": "Pegasus",
        "price": 3450,
        "currency": "TRY"
      },
      "createdAt": "2026-03-27T11:10:00.000Z"
    }
