      "imageWebUrl": "https://storage.example.com/banners/yaz-okulu-web.jpg",
      "imageWebThumbUrl": "https://storage.example.com/banners/yaz-okulu-web_thumb.jpg",
      "imageMobileUrl": "https://storage.example.com/banners/yaz-okulu-mobil.jpg",
